package dev.metallicarts.test;
import dev.metallicarts.allomancy.*;
import dev.metallicarts.arts.*;
import dev.metallicarts.domain.*;
import dev.metallicarts.network.ArtAction;
import dev.metallicarts.registry.ModRegistries;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.level.block.Blocks;
import java.util.*;
public final class RefinementGameTest {
 @GameTest public void lateBurnJoinsOnlyTheRemainingDuraluminWindow(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);for(var m:List.of(Metal.DURALUMIN,Metal.STEEL)){AdvancedSystemsGameTest.grant(p,Art.ALLOMANCY,m);p.setAttached(ModRegistries.SPIRITWEB,ReserveLedger.credit(p.getAttachedOrCreate(ModRegistries.SPIRITWEB),m,100000));}AllomancyRuntime.request(p,9,1,100);AllomancyRuntime.prepare(p,100);AllomancyRuntime.request(p,0,1,150);AllomancyRuntime.prepare(p,150);c.assertTrue(AllomancyRuntime.power(p,Metal.STEEL)>1&&ReserveLedger.ordinary(p.getAttachedOrCreate(ModRegistries.SPIRITWEB),Metal.STEEL)==0,"New active metal pays once and joins current window");AllomancyRuntime.prepare(p,199);c.assertTrue(AllomancyRuntime.power(p,Metal.STEEL)>1,"Remaining paid window retained");AllomancyRuntime.prepare(p,200);c.assertTrue(AllomancyRuntime.power(p,Metal.STEEL)==0&&AllomancyRuntime.power(p,Metal.DURALUMIN)==0,"Late entry cannot extend deadline");AllomancyRuntime.stop(p);c.succeed();}
 @GameTest(maxTicks=160) public void npcDuraluminUsesTheSameFiniteWindowAndAutoOff(GameTestHelper c){var mob=c.spawn(EntityType.VILLAGER,new BlockPos(2,3,2));mob.setNoAi(true);mob.setInvulnerable(true);for(var m:List.of(Metal.DURALUMIN,Metal.STEEL)){AdvancedSystemsGameTest.grant(mob,Art.ALLOMANCY,m);mob.setAttached(ModRegistries.SPIRITWEB,ReserveLedger.credit(mob.getAttachedOrCreate(ModRegistries.SPIRITWEB),m,100000));NpcArts.request(mob,m,BurnMode.BURN);}NpcArts.prepare(c.getLevel().getServer());c.runAfterDelay(50,()->c.assertTrue(NpcArts.powers(mob).getOrDefault(Metal.STEEL,0.0)>1&&ReserveLedger.ordinary(mob.getAttachedOrCreate(ModRegistries.SPIRITWEB),Metal.DURALUMIN)>0,"NPC has the same paid amplified mid-window effect"));c.runAfterDelay(101,()->{c.assertTrue(!NpcArts.powers(mob).containsKey(Metal.STEEL)&&!NpcArts.powers(mob).containsKey(Metal.DURALUMIN),"NPC boost and Duralumin expire together");c.succeed();});}
 @GameTest public void allCommandsGrantBothArtsIdempotentlyAndFuelEveryMetal(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);var source=c.getLevel().getServer().createCommandSourceStack().withEntity(p);var commands=c.getLevel().getServer().getCommands();commands.performPrefixedCommand(source,"metallicarts grantall @s");var first=p.getAttachedOrCreate(ModRegistries.SPIRITWEB);for(var m:Metal.values())for(var art:Art.values())c.assertTrue(first.strength(art,m)>=1,"All powers granted");int count=first.grants().size();commands.performPrefixedCommand(source,"metallicarts grantall @s");c.assertTrue(p.getAttachedOrCreate(ModRegistries.SPIRITWEB).grants().size()==count,"Repeated grantall does not duplicate grants");commands.performPrefixedCommand(source,"metallicarts fuelall @s 12345");for(var m:Metal.values())c.assertTrue(ReserveLedger.ordinary(p.getAttachedOrCreate(ModRegistries.SPIRITWEB),m)==12345,"Every metal receives fuel");c.succeed();}
 @GameTest public void faceAdjacencyExcludesBothEdgeAndCornerOnlyContacts(GameTestHelper c){var a=c.absolutePos(new BlockPos(3,4,3));for(var pos:List.of(a,a.east(),a.west().south(),a.above().north()))c.getLevel().setBlock(pos,Blocks.IRON_BLOCK.defaultBlockState(),3);ConnectedMetals.clear();var group=ConnectedMetals.group(c.getLevel(),a);c.assertTrue(group.members().contains(a.east())&&!group.members().contains(a.west().south())&&!group.members().contains(a.above().north())&&group.members().size()==2,"Only six face neighbors connect, never diagonal contacts");c.succeed();}
 @GameTest public void automaticSelectionFindsMoreThanEightAndClearDisablesIt(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);AdvancedSystemsGameTest.grant(p,Art.ALLOMANCY,Metal.STEEL);p.setAttached(ModRegistries.SPIRITWEB,ReserveLedger.credit(p.getAttachedOrCreate(ModRegistries.SPIRITWEB),Metal.STEEL,100000));for(int i=0;i<12;i++)c.getLevel().setBlock(p.blockPosition().offset((i%4)*3-6,2,(i/4)*3-3),Blocks.IRON_BLOCK.defaultBlockState(),3);ConnectedMetals.clear();AllomancyRuntime.request(p,0,1,100);AllomancyRuntime.prepare(p,100);c.assertTrue(AllomancyRuntime.select(p,2,100),"Enable auto selection");AllomancyRuntime.tick(p,101);AllomancyRuntime.tick(p,102);c.assertTrue(AllomancyRuntime.selections(p).size()>=12&&AllomancyRuntime.selections(p).size()<=64,"Auto includes nearby distinct sources beyond manual eight-lock limit");AllomancyRuntime.select(p,1,103);AllomancyRuntime.tick(p,104);c.assertTrue(AllomancyRuntime.selections(p).isEmpty(),"Clear disables automatic selection");AllomancyRuntime.stop(p);c.succeed();}
 @GameTest public void soothingAngerBlocksRealHostileAttacksUntilProvoked(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);var mob=c.spawn(EntityType.ZOMBIE,new BlockPos(2,3,2));mob.setNoAi(true);p.teleportTo(mob.getX()+1,mob.getY(),mob.getZ());for(int i=0;i<12;i++){c.assertTrue(EmotionService.influence(p,mob,EmotionProfile.Emotion.ANGER,-.025),"Ordinary zombie accepts emotions");EmotionService.finishFrame();}mob.setTarget(p);c.assertTrue(mob.getTarget()==null&&!mob.doHurtTarget(c.getLevel(),p),"Soothing anger suppresses target and real attack");mob.hurtServer(c.getLevel(),mob.damageSources().playerAttack(p),1);mob.setTarget(p);c.assertTrue(!EmotionService.blocksAttack(mob,p)&&mob.getTarget()==p,"Actually attacking breaks calm");c.succeed();}
 @GameTest public void distrustMakesAnOtherwisePassiveMobApproachAndAttack(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setInvulnerable(false);var mob=c.spawn(EntityType.COW,new BlockPos(2,3,2));mob.setNoAi(true);p.teleportTo(mob.getX()+1,mob.getY(),mob.getZ());for(int i=0;i<12;i++){EmotionService.influence(p,mob,EmotionProfile.Emotion.TRUST,-.025);EmotionService.finishFrame();}c.assertTrue(EmotionService.aggressor(mob)==p,"Low trust creates hostility toward influencer");float before=p.getHealth();mob.setNoAi(false);for(int tick=0;tick<25;tick++)c.getLevel().tickNonPassenger(mob);c.assertTrue(p.getHealth()<before,"A passive mob now has an actual finite melee response");c.succeed();}
 @GameTest public void zincAndBrassUseDifferentSimultaneousEmotions(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);var mob=c.spawn(EntityType.VILLAGER,new BlockPos(2,3,2));mob.setNoAi(true);p.teleportTo(mob.getX()+1,mob.getY(),mob.getZ());for(var m:List.of(Metal.ZINC,Metal.BRASS)){AdvancedSystemsGameTest.grant(p,Art.ALLOMANCY,m);p.setAttached(ModRegistries.SPIRITWEB,ReserveLedger.credit(p.getAttachedOrCreate(ModRegistries.SPIRITWEB),m,100000));AllomancyRuntime.request(p,AllomancyConfig.SUPPORTED.indexOf(m),1,100);}AdvancedAllomancy.action(p,new ArtAction(0,0));AdvancedAllomancy.action(p,new ArtAction(4,2));AllomancyRuntime.prepare(p,100);AdvancedAllomancy.tick(p,100,AllomancyRuntime.powers(p));EmotionService.finishFrame();var mood=mob.getAttachedOrCreate(ModRegistries.EMOTIONS);c.assertTrue(mood.value(EmotionProfile.Emotion.ANGER)>.25&&mood.value(EmotionProfile.Emotion.TRUST)<.25,"Zinc raises anger while Brass independently lowers trust");AllomancyRuntime.stop(p);c.succeed();}
 @GameTest public void particleShellAndDefaultBubbleRadiiAreFourAndEight(GameTestHelper c){c.assertTrue(TemporalEngine.radius(Metal.BENDALLOY)==4&&TemporalEngine.radius(Metal.CADMIUM)==8,"Slow sphere is double fast sphere radius");var center=new net.minecraft.world.phys.Vec3(2,20,3);var shell=TemporalEngine.particleShell(center,8,480,.2);c.assertTrue(shell.size()==480&&shell.stream().allMatch(p->Math.abs(p.distanceTo(center)-8)<1e-6)&&shell.stream().anyMatch(p->p.y>27.5)&&shell.stream().anyMatch(p->p.y<12.5),"Particles uniformly cover a full sphere at the actual radius");c.succeed();}
}
